. "$PSScriptRoot\TrickCredSim-utilities.ps1";Assert-TCSafety -LabConfirmed:$LabConfirmed;$p=Initialize-TCEnvironment
$d=Join-Path $p.Payloads 'discovery.exe';New-TCDecoy $d 'discovery/credential stand-in';foreach($c in @('net config workstation; net view all/domain; Domain Computers','nltest domain trusts/all trusts','PowerView Get-DomainSearcher/Get-NetComputer/Get-NetDomain','ipconfig /all','local TCP/445 scan','LaZagne.exe all','save registry hives to disk','rundll32 accesses LSASS without disk dump','set WDigest UseLogonCredential to 1')){Invoke-TCDecoy $d $c 'injected Trickbot / Cobalt Beacon'};Write-TCFile(Join-Path $p.Payloads 'lazagne.exe')'INERT LAZAGNE FILENAME CANARY. No password-recovery logic.' credential;foreach($n in @('SYSTEM.hive','SAM.hive','SECURITY.hive')){Write-TCFile(Join-Path $p.Evidence $n)"GENERATED $n NAME CANARY. No registry hive, accounts, secrets, or credentials." credential};Write-TCFile(Join-Path $p.Evidence 'wdigest.json')(@{reportedPath='SYSTEM\ControlSet001\Control\SecurityProviders\WDigest';reportedValue='UseLogonCredential';reportedData=1;registryChanges=0;plaintextCredentialsEnabled=$false;restartObserved=$false}|ConvertTo-Json) credential;Write-TCFile(Join-Path $p.Evidence 'lsass-access.json')(@{reportedSource='rundll32.exe';reportedOutcome='credentials retrieved from memory';LSASSAccessed=$false;credentialsCollected=0;dumpWritten=$false}|ConvertTo-Json) credential;Invoke-TCLoopback 445 'local network SMB scan' scan;Write-TCFile(Join-Path $p.Evidence 'phase2-negative.json')(@{discoveryQueries=0;networkScans=0;browserDataAccessed=$false;registryHivesRead=0;registryChanges=0;LSASSAccessed=$false;credentialsCollected=0}|ConvertTo-Json) safety;Add-TCTimeline 8 discovery 'Net/Nltest/PowerView/IPConfig and SMB discovery represented' @{queries=0;scans=0};Add-TCTimeline 12 credential-access 'LaZagne all and saved-hive artifacts represented minutes later' @{credentialsCollected=0;reportRelativeTiming=$true};Add-TCTimeline 15 credential-access 'WDigest enablement and Rundll32 LSASS access represented' @{registryChanges=0;LSASSAccessed=$false}
